<?php require_once __DIR__.'/includes/bootstrap.php';if(current_user())redirect('dashboard.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$s=$conn->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&$u['is_active']&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'full_name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role'],'email_verified'=>(int)$u['email_verified']];log_activity($conn,(int)$u['id'],'login','Successful login');if(!$u['email_verified'])redirect('verify_notice.php');redirect('dashboard.php');}flash('error','Invalid email/password or inactive account.');redirect('login.php');}page_header('Login');?><div class="auth-card"><h1>Welcome back</h1><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button class="btn full">Sign in</button></form><p class="muted">No account? <a href="register.php">Register</a></p></div><?php page_footer();?>